(() => {
  "use strict";
  const $ = id => document.getElementById(id);
  const STORAGE_KEY = "tradethesis.support-resistance-room.preview.v1";
  const chartRoot = "assets/support-resistance-charts/";
  const modules = [
    {id:1,name:"Understand",range:"Lessons 1–2",outcome:"Describe the chart before explaining it."},
    {id:2,name:"Find",range:"Lessons 3–5",outcome:"Choose fewer, more defensible areas."},
    {id:3,name:"Draw & evaluate",range:"Lessons 6–8",outcome:"Explain boundary choices without magic scores."},
    {id:4,name:"Read reactions",range:"Lessons 9–11",outcome:"Let evidence refine your first read."},
    {id:5,name:"Breakouts & failures",range:"Lessons 12–14",outcome:"Judge the sequence, not one candle."},
    {id:6,name:"Apply & review",range:"Lessons 15–18",outcome:"Use conditional scenarios and accept uncertainty."}
  ];
  const lessons = [
    {id:1,module:1,title:"What support and resistance actually tell you",duration:"12–15 min",summary:"Prior price behaviour can make an area worth examining. It does not make that area a guaranteed barrier or a complete trading signal.",outcome:"Describe prior reactions while keeping observation separate from prediction.",chart:"L01-A-01-clean.png",chartStages:[{"file":"L01-A-01-clean.png","label":"Start · unlabelled","alt":"Illustrative price sequence before any support area is drawn. Several candles react near a similar lower area.","caption":"Start unlabelled. Describe the lower reactions you can see before naming the area.","question":"Before naming anything, what stands out about where price pauses, turns or moves away?","instructions":"Describe the visible sequence in your own words. Try to separate what the candles do from any explanation of why they do it.","cue":"You are not expected to know the next move. Start with evidence that is visible now.","teaching":{"title":"Start with what the chart shows","paragraphs":["This first view has no labels. You are not expected to know the correct term yet. Describe what price does in the candles shown, without guessing what caused the movement."],"points":["Where does price pause, turn or move away?","Do similar reactions appear more than once, or is the evidence still unclear?"],"takeaway":"Record an observation, not a prediction. Leave the reason for the move open."}},{"file":"L01-A-02-band.png","label":"Reveal 1 · broad area","alt":"The same illustrative lower-reaction sequence with a broad neutral band around the related reactions.","caption":"The broad band gathers related reactions. It is an area, not one exact price.","question":"What does the band help you notice—and what does it not guarantee?","instructions":"Compare the shaded area with the candle reactions. Explain what the band summarises and what it cannot tell you about the next move.","cue":"The band organises prior behaviour. It does not make the next reaction certain.","teaching":{"title":"A band groups nearby reactions","paragraphs":["The shaded band gathers a broad area around the places where price previously slowed or turned. It makes the repeated relationship easier to inspect than a hairline would when the turning prices vary.","The band is an annotation to help us read the chart. It is not an official boundary discovered by the market, and its width is not uniquely determined by this example."],"points":["Observation: several reactions occur in a similar broad area.","Interpretation: the area may be worth watching when reading the chart.","Limit: the band alone does not predict what price will do next."],"takeaway":"A useful area summarises evidence; it does not turn that evidence into a rule."}},{"file":"L01-A-03-labelled.png","label":"Reveal 2 · prior reaction area","alt":"The lower band is labelled prior reaction area.","caption":"“Prior reaction area” describes the evidence without claiming who caused the turn or predicting the next move.","question":"Why is “prior reaction area” a safer first label than “buyers defended support”?","instructions":"Write one sentence about what is visible and one sentence about what remains unknown.","cue":"A price chart shows the sequence of prices; it does not directly show every participant's intentions.","teaching":{"title":"Describe the evidence before explaining it","paragraphs":["“Prior reaction area” is a deliberately descriptive label. It says that price reacted near this area before, without pretending we know the full cause of each turn.","A statement such as “buyers defended the level” makes a stronger claim about hidden participants. The chart excerpt alone does not establish who acted, why they acted or whether the same response will happen again."],"points":["Visible: price turned upward near this area on earlier occasions.","Not established by this chart alone: a particular group caused the turns.","Still uncertain: how price will behave if it returns."],"takeaway":"Good analysis starts with what you can point to, then labels interpretation as interpretation."}},{"file":"L01-A-04-support-label.png","label":"Reveal 3 · support area","alt":"The same illustrative sequence with the lower area labelled support area.","caption":"Support names a type of prior price behaviour; it does not promise a future hold.","question":"In this example, what does the word support mean?","instructions":"Explain the term using the visible sequence. Avoid describing support as an unbreakable floor or a trade signal.","cue":"Support describes where falling price previously slowed, paused or turned upward.","teaching":{"title":"Support describes prior behaviour","paragraphs":["Support is an area where falling price has previously slowed, paused or turned upward. The word names the behaviour visible in the history shown; it does not mean price must stop there next time.","A support area is not an entry signal by itself. Later lessons will cover how to choose boundaries and how to evaluate newer behaviour. For now, the important distinction is between describing a prior reaction and predicting a future one."],"points":["The label fits because earlier falling price reacted upward near the area.","A later move through the area would not erase those earlier reactions.","A label alone does not provide a trade plan."],"takeaway":"Use “support” to describe the past reaction—not to promise a future reversal."}},{"file":"L01-B-01-clean.png","label":"Compare · unlabelled upper reactions","alt":"Illustrative price rises into a broad upper area, turns down, returns and turns down again, without annotations.","caption":"Before naming resistance, describe what price did as it rose into the upper area.","question":"What happened when price rose into the upper area on the visible occasions?","instructions":"Describe the reactions first. Do not assume every future visit will have the same result.","cue":"Use the same observe-first habit on the upper side of the chart.","teaching":{"title":"Now inspect the counterpart","paragraphs":["This second illustration reverses the direction of approach. Price rises into a similar broad upper area and previously pauses or turns down near it.","Do not treat the chart as a mirror-image law. It is simply another example of how prior price behaviour can make an area worth examining."],"points":["What repeats in the visible sequence?","What is similar to the lower-reaction example?","What is still unknown about the next visit?"],"takeaway":"Use the same evidence-first method whether the earlier reaction was upward or downward."}},{"file":"L01-B-02-band.png","label":"Reveal 4 · upper reaction area","alt":"The upper-reaction chart with a broad neutral band around related upper reactions.","caption":"The band groups nearby upper reactions without claiming one exact ceiling.","question":"What does the band summarise in this upper-reaction example?","instructions":"Point to the related reactions and explain why an area can be more useful than an exact line here.","cue":"The area captures variation in the visible turning prices; it is not a perfect ceiling.","teaching":{"title":"The area can contain variation","paragraphs":["The shaded band gathers the related upper reactions. The turns need not occur at one identical price for the area to help describe what happened.","A broad area can also be drawn too widely. Boundary selection and how to defend the width are separate skills taught later, so do not solve them with an arbitrary fixed number here."],"points":["The band should relate to the reactions that prompted it.","A band is a summary of those reactions, not evidence that all prices inside it are equivalent.","Different but consistently explained boundaries may be reasonable."],"takeaway":"An area should be wide enough to describe the evidence, but not so wide that it stops being useful."}},{"file":"L01-B-04-resistance-label.png","label":"Reveal 5 · resistance area","alt":"The upper reaction area labelled resistance area.","caption":"Resistance names an area where rising price previously slowed, paused or turned downward.","question":"What does resistance mean in this example—and what would be too strong a conclusion?","instructions":"Give a plain-language definition, then name one thing the chart does not prove.","cue":"Resistance describes previous reactions from rising price; it does not guarantee the next one.","teaching":{"title":"Resistance describes the upper-side counterpart","paragraphs":["Resistance is an area where rising price has previously slowed, paused or turned downward. Like support, it describes prior price behaviour rather than guaranteeing the next result.","A chart can support the statement “price turned down near this area before.” It cannot, by itself, prove a particular participant's motive or that price will turn down there again."],"points":["Support: prior downward movement slowed or turned upward near an area.","Resistance: prior upward movement slowed or turned downward near an area.","Both: areas for organising prior evidence, not certainty about the future."],"takeaway":"The terms are useful because they describe what happened—not because they make it happen again."}},{"file":"L01-A-05-breakdown.png","label":"Counterexample · area crossed","alt":"Later illustrative candles trade decisively below the previously marked lower reaction area.","caption":"Later candles trade through the area. Earlier reactions remain part of the history, but the area was not a guaranteed barrier.","question":"Now that later candles have crossed the marked support area, what is the most defensible conclusion?","instructions":"Explain what the new evidence changes and what it does not erase. Do not jump straight to the opposite prediction.","cue":"An area can be useful context and still fail to contain a later move.","teaching":{"title":"A zone can be crossed","paragraphs":["The later candles have moved through the marked area. That changes the current reading: the area did not contain this move. It does not erase the earlier reactions that made the area worth marking in the first place.","Do not jump from “support did not hold here” to “price must now fall forever” or “resistance must work next.” One outcome does not prove its opposite. Breakout confirmation, retests and failed breakouts belong in later lessons."],"points":["Earlier evidence remains historical evidence.","The new candles contradict the idea that this area is an unbreakable floor.","The next move is still uncertain; the chart gives context, not a guarantee."],"takeaway":"Update your interpretation when new evidence arrives, without pretending the earlier observation never mattered."}},{"file":"L01-PRACTICE-A-01-clean.png","label":"Your turn · clearer reactions","alt":"Independent practice chart with two relatively clear lower reactions and upward moves away from each, no area drawn.","caption":"Practice: choose what the visible evidence supports before revealing a reference.","question":"What visible evidence makes this a reasonable candidate reaction area?","instructions":"Identify the reactions you are using. Say what your reading supports and one conclusion it does not justify.","cue":"The aim is a defensible explanation, not an exact pixel-perfect band.","teaching":{"title":"Practise the observation-to-interpretation step","paragraphs":["This example gives you a fresh sequence. Before viewing the reference, identify the visible reactions you are relying on and explain why they might belong to the same broad area.","You do not need to reproduce the same boundaries as the reference. A nearby area may also be defensible if you can explain which reactions it includes and why."],"points":["Name the evidence you used.","State the limited interpretation it supports.","Keep one uncertainty or alternative open."],"takeaway":"Try the reasoning yourself before comparing it with the example answer."}},{"file":"L01-PRACTICE-A-02-reference.png","label":"Worked answer · clearer reactions","alt":"Reference view showing one defensible broad lower reaction area on the practice chart.","caption":"One defensible answer highlights the area containing the clearer repeated lower reactions.","question":"Compare your answer with this reference. What makes the reference defensible?","instructions":"Compare the reactions included and excluded. Revise your explanation if the reference reveals evidence you missed.","cue":"The reference demonstrates reasoning; it is not the only acceptable drawing.","teaching":{"title":"One defensible worked read","paragraphs":["The reference marks one broad lower area that contains the clearer repeated reactions. The reasoning is that more than one visible move turned upward near a similar region, so the area summarises something actually present in the sequence.","A sound answer would not say the area must hold, that a trade should be taken there, or that the chart proves who caused the turns. Slightly different boundaries may be reasonable if they reflect the same evidence consistently."],"points":["Strong: “Price turned upward near this broad area on more than one occasion.”","Too strong: “Buyers will defend this exact price again.”","Useful self-check: can you point to the reactions that support each edge?"],"takeaway":"Judge the explanation and its limits—not whether your drawing exactly matches the reference."}},{"file":"L01-PRACTICE-B-01-clean.png","label":"Your turn · ambiguous evidence","alt":"Independent practice chart with uneven lower reactions; no precise repeated area is clearly established.","caption":"Practice with weaker evidence. It is acceptable to mark a broad candidate area or remain unsure.","question":"Is there enough evidence to name one clear repeated reaction area here?","instructions":"Choose a tentative reading or say that the evidence is unclear. Explain what makes you more or less confident.","cue":"Not every chart offers a clean example. Uncertainty is a valid result.","teaching":{"title":"Now compare a less tidy case","paragraphs":["This chart has uneven lower reactions. There may be a broad candidate area, but the evidence is less clustered than in the previous example.","Resist the urge to force a precise zone because the exercise asks for one. Good chart reading includes recognising when the visible evidence is too weak to support a confident label."],"points":["Ask whether the reactions are genuinely related or only loosely nearby.","A broad candidate area is one possible reading, not a requirement.","“Unclear for now” can be more defensible than inventing precision."],"takeaway":"Confidence should follow the evidence. Do not make the chart look clearer than it is."}},{"file":"L01-PRACTICE-B-02-reference.png","label":"Worked answer · uncertainty accepted","alt":"Reference view of the ambiguous practice chart with a broad candidate area and a note that uncertainty is acceptable.","caption":"A broad candidate area is possible, but the reference explicitly accepts an unclear reading.","question":"Why is “unclear” still a defensible answer for this chart?","instructions":"Explain which evidence is weaker here than in the previous example. Do not treat the reference band as compulsory.","cue":"A model answer is a guide to reasoning, not a mandatory drawing.","teaching":{"title":"The model answer leaves room for uncertainty","paragraphs":["The reference shows a broad candidate area, but the reactions are not as well clustered as in the clearer example. The correct teaching point is not “always draw a band”; it is “explain how much the evidence supports your choice.”","If you wrote that the area is too ambiguous to label confidently, that is defensible. If you proposed a broad area and identified the uncertainty, that can also be defensible."],"points":["Acknowledge the uneven reactions.","Avoid pretending a broad candidate area is an exact level.","Explain what additional price behaviour would make your reading clearer."],"takeaway":"A careful “not enough evidence yet” is better than false precision."}}],alt:"Illustrative candles decline into a broad lower price area, move upward, and later revisit a similar area. No zones are drawn.",prompt:"What does a support/resistance zone tell you—and what does it not tell you?",instructions:"Describe the visible reactions first. Avoid claiming that the next move is known.",cue:"A zone is an area of interest based on prior price behaviour, not a promise about the next move.",quiz:{"q":"Price later moves through an area where it reacted before. Which reading is most defensible?","options":["The earlier reactions never mattered, so the area was useless.","The area has been crossed in this sequence; the earlier reactions remain part of the history, but the area was not a guaranteed barrier.","The same participants must now reverse direction and make price fall further."],"correct":1,"feedback":"The new candles change the current reading without erasing earlier evidence. A support/resistance area gives context, not certainty about the next move or a complete trade signal."}},
    {id:2,module:1,title:"Read structure before drawing",duration:"15 min",summary:"Read the broad path of price before marking areas. Relative swing highs and lows help distinguish rising structure, falling structure, a range, or a transition that is not yet clear.",outcome:"Classify the broad structure and point to the major turns that support that description.",chart:"L02-A-01-clean.png",chartStages:[{"file":"L02-A-01-clean.png","label":"Start · rising sequence","alt":"Illustrative rising candlestick sequence with no reference markings.","caption":"Start with the broad path. Is the sequence generally rising, falling, ranging or unclear?","question":"Which description best fits the overall path of this first sequence?","instructions":"Look at the larger turns rather than counting green and red candles. Give one piece of visible evidence for your classification.","cue":"Describe the broad path before bringing in zones or trade decisions.","teaching":{"title":"Describe the path before naming every turn","paragraphs":["This chart is a made-up teaching example. Begin with the broad path of price, not the colour of one candle or the latest move.","A useful first description should be supported by how the turning points change across the sequence. You do not need to identify every small fluctuation to describe the overall direction."],"points":["Does the sequence generally make progress upward?","Which later turning points would you compare with earlier ones?","What part of the chart makes your description less certain?"],"takeaway":"Your first classification is a working description of the evidence shown—not a prediction."}},{"file":"L02-A-02-turns.png","label":"Reveal 1 · candidate turns","alt":"The rising sequence with a selection of candidate local turning points marked.","caption":"Candidate turns are highlighted. Which points explain the broad path, and which are minor fluctuations?","question":"Which marked turns help explain the broad path—and which could be left out?","instructions":"Choose a small set of useful turns. Explain how they help you describe the sequence rather than simply listing every wiggle.","cue":"A turning point is relative to the surrounding sequence; it is not defined by one special candle shape.","teaching":{"title":"Swing points are relative turns","paragraphs":["A swing high or swing low is a local turning point in the surrounding price sequence. It is not defined by one candle shape, and a chart can contain many small turns.","The purpose here is not to mark every wiggle. Choose turns that help another person understand the broad path. A turn is also easier to identify after price has moved away from it; in real time, its importance may not yet be clear."],"points":["A swing high is a local peak relative to the moves around it.","A swing low is a local trough relative to the moves around it.","Not every local turn carries equal information about the larger path."],"takeaway":"Choose turns for the question you are asking, not because every fluctuation deserves a label."}},{"file":"L02-A-03-structure-reference.png","label":"Reveal 2 · worked rising read","alt":"The rising sequence labelled with generally higher highs and higher lows.","caption":"One worked read: relative highs and lows generally move higher. This is a reference, not the only defensible set of turns.","question":"Why does the reference describe this as generally rising structure?","instructions":"Point to the relationship between earlier and later turns. Mention one feature that does not invalidate the broader reading.","cue":"A pullback can occur within a generally rising sequence.","teaching":{"title":"What makes the rising reading defensible?","paragraphs":["The reference marks a restrained set of turns whose later highs and lows generally sit above earlier ones. That relationship—not a string of green candles—is the main reason for the rising description.","Small pullbacks and red candles do not automatically reverse the broader structure. The label remains a description of the sequence shown and does not say what must happen next."],"points":["Evidence: the broad sequence of relative highs and lows moves upward.","Limit: one example cannot establish that every future pullback will hold.","Alternative: if the later turns begin to overlap or stop progressing, the rising description may become less useful."],"takeaway":"A good structure label points to relationships between turns, not to isolated candles."}},{"file":"L02-B-01-clean.png","label":"Compare · falling sequence","alt":"Illustrative falling sequence with upward retracements and no reference labels.","caption":"Describe a falling sequence before checking any reference labels.","question":"What visible relationship between turns would support a generally falling description?","instructions":"Look for how later highs and lows compare with earlier ones. Do not confuse a temporary upward retracement with a full change in structure.","cue":"A sequence can contain upward candles while the broader path is still declining.","teaching":{"title":"Apply the same question to a falling sequence","paragraphs":["Use the same method rather than changing the rule because the chart is moving down. Look at the sequence of meaningful highs and lows across the visible excerpt.","Some candles rise during a decline. Those retracements do not automatically make the overall path rising; the broader relationship between the turns matters."],"points":["Compare later highs with earlier highs.","Compare later lows with earlier lows.","If the turns are mixed or the excerpt is too short, say so."],"takeaway":"Use the same structural reasoning in both directions."}},{"file":"L02-B-02-structure-reference.png","label":"Reveal 3 · worked falling read","alt":"The falling sequence annotated with a selection of lower highs and lower lows.","caption":"This reference identifies generally lower highs and lower lows. The reasoning matters more than exact marker placement.","question":"What evidence makes the falling description reasonable, and what would make you reconsider it?","instructions":"Explain the relation between the swings. Avoid saying a declining structure means every next candle must be down.","cue":"An interpretation can be reasonable and still need revision as new candles arrive.","teaching":{"title":"What makes the falling reading defensible?","paragraphs":["The reference shows a sequence in which the later highs and lows are generally lower than the earlier ones. That is stronger evidence for a falling structure than simply counting down-coloured candles.","A larger upward move or a sequence of higher turning points could weaken or change the reading. A structure label should be revisited when the price sequence changes, rather than defended at all costs."],"points":["Evidence: generally lower relative highs and lows.","Not implied: uninterrupted selling or a guaranteed next decline.","Possible revision: later turns begin to rise or overlap enough that the original description no longer fits."],"takeaway":"A useful label remains open to revision when the evidence changes."}},{"file":"L02-C-01-clean.png","label":"Compare · possible range","alt":"Illustrative price movement back and forth inside a broad region, without boundaries drawn.","caption":"This sequence moves back and forth within a broad area rather than making clear sustained progress in one direction.","question":"Does this sequence make clear sustained progress in one direction, or mostly move back and forth?","instructions":"Describe the broad behaviour before drawing a boundary. A range need not have perfectly flat highs and lows.","cue":"A trading range describes the movement shown; it is not a permanent container.","teaching":{"title":"A range is back-and-forth behaviour","paragraphs":["Here, price moves back and forth within a broad region instead of steadily extending its progress in one direction. The highs and lows are uneven, so the range should not be imagined as a perfectly rectangular box.","A short pause inside a stronger trend can resemble a range. The label should match the amount and quality of evidence visible, and may remain provisional when the excerpt is limited."],"points":["Look for repeated movement in both directions within a broad region.","Do not demand identical highs and lows.","Ask whether there is enough evidence to distinguish a range from a temporary pause."],"takeaway":"Describe what the sequence is doing before imposing neat boundaries on it."}},{"file":"L02-C-02-major-turns.png","label":"Reveal 4 · major turns","alt":"The range sequence with a small set of major turning points marked.","caption":"Major turns help communicate the broad back-and-forth path. Not every local turn needs a label.","question":"Why were these major turns selected instead of marking every small fluctuation?","instructions":"Explain how a limited set of turns communicates the broad structure. Point out one fluctuation you would leave unmarked.","cue":"Editing the chart is part of making a defensible reading.","teaching":{"title":"Choose turns that communicate the range","paragraphs":["The reference marks a small set of larger turns. They make the broad back-and-forth pattern easier to see without covering the chart in labels.","A different reader may choose a nearby turn. Exact marker placement matters less than whether the chosen points help explain the overall behaviour and are used consistently."],"points":["Keep turns that clarify the broad path.","Leave minor fluctuations unmarked when they do not change the classification.","Do not select turns only because of what happened later."],"takeaway":"A few well-explained turns often teach more than a dense set of marks."}},{"file":"L02-C-03-range-reference.png","label":"Reveal 5 · approximate range","alt":"The range sequence with a broad bracket marking an approximate trading region.","caption":"A broad bracket summarises an approximate region. It is not a precision trading signal.","question":"What does the broad range bracket help you communicate—and what is still uncertain?","instructions":"Describe the approximate region and one reason its boundaries should not be treated as exact. Zone drawing comes later.","cue":"This bracket describes structure; it is not a support/resistance entry signal.","teaching":{"title":"The bracket is an approximation, not a law","paragraphs":["The bracket summarises the broad region in which price has been moving back and forth. It is a visual aid for describing structure, not a promise that price will stop at its upper or lower edge.","Do not turn this into a boundary-drawing lesson yet. Here, the bracket is only a way to communicate the observed range; support and resistance boundaries are developed later in the course."],"points":["It helps make the broad region visible.","It does not provide exact, universal boundaries.","Price can move outside the displayed region; a range label must be revisited when that happens."],"takeaway":"Use the bracket to describe where price has been—not to guarantee where it will remain."}},{"file":"L02-D-01-early-state.png","label":"Transition · early state","alt":"First segment of an illustrative rise with the later candles hidden.","caption":"The earlier rise is visible, but the later transition is hidden. Make a provisional classification from the evidence shown now.","question":"Based only on this early state, how would you describe the structure right now?","instructions":"Give a provisional label and one reason. It is acceptable to say the structure is rising with recent consolidation, or that more evidence is needed.","cue":"Do not use candles you have not seen yet to grade your first reading.","teaching":{"title":"Do not borrow evidence from the future","paragraphs":["At this point, the sequence has a clear earlier rise, but you have not yet seen enough of the later movement to know how the transition will develop. A provisional description such as “rising structure with recent consolidation” is reasonable.","There may be more than one defensible first read. The aim is to record what the visible evidence supports at this moment—not to guess the final shape of the chart."],"points":["Use only the candles currently visible.","State your confidence and what remains unclear.","Keep the first reading so you can compare it after the reveal."],"takeaway":"A later outcome does not make an earlier judgement wrong if that evidence was not available yet."}},{"file":"L02-D-02-later-state.png","label":"Transition · later evidence","alt":"The full illustrative sequence showing an earlier rise giving way to more overlapping, less directional movement and a possible range.","caption":"With more candles, price overlaps and becomes less directional. A possible range is more defensible now; do not use future evidence to grade the earlier read.","question":"What changed when the later candles appeared, and how should your original label change?","instructions":"Compare the early and later states. Identify the new evidence and revise the structure description without claiming the transition began at one objectively perfect candle.","cue":"Revision is part of chart reading; it is not proof your first observation was careless.","teaching":{"title":"New evidence can change the best description","paragraphs":["The later view shows more overlap and less directional progress. A transition toward a range is now more defensible than it was in the early view because additional candles show the change in behaviour.","There is not necessarily one objectively perfect candle where a trend “became” a range. A reader might describe the sequence as an uptrend with consolidation or as a developing range. The explanation should identify the new overlap and reduced progress, and preserve the uncertainty."],"points":["What changed: price overlaps more and stops extending the earlier rise as clearly.","What remains uncertain: the exact transition point and what price will do next.","What to avoid: claiming the later range was obvious from the first pause."],"takeaway":"A defensible read can change when the evidence changes—explain why, rather than pretending you knew all along."}},{"file":"L02-E-01-practice.png","label":"Your turn · independent practice","alt":"Independent practice chart showing a decline that becomes less directional and develops into overlapping movement, without answer markings.","caption":"Make an independent structure read before opening the reference.","question":"How would you describe the earlier part of this sequence and the later part?","instructions":"Choose three to five useful turns, classify the broad structure and write one sentence citing the evidence. Transition/unclear is acceptable if your reasoning supports it.","cue":"The reference is one defensible reading, not a pixel-perfect answer key.","teaching":{"title":"Put the method together","paragraphs":["This independent example begins with a decline and later becomes less directional. Before you reveal the reference, identify the major turns and describe the broad sequence in your own words.","Try to explain both the earlier and later behaviour. A sentence such as “an earlier decline followed by increasingly overlapping movement” is more informative than “bearish” alone."],"points":["Select a small, explainable set of turns.","Use relative highs and lows or the amount of directional progress as evidence.","Say where the classification becomes less certain."],"takeaway":"A strong answer states what changed in the chart and what remains interpretive."}},{"file":"L02-E-02-reference.png","label":"Worked answer · transition accepted","alt":"Reference interpretation of the practice chart showing an earlier decline followed by more overlap; the transition point remains interpretive.","caption":"The reference describes an earlier decline followed by less directional overlap; the exact transition point remains interpretive.","question":"Compare with the reference. Which parts of your reasoning are supported, and where could uncertainty remain?","instructions":"Review the turns you selected and how you described the transition. Keep any defensible differences and revise unsupported claims.","cue":"A reasonable alternative is acceptable when you can point to the evidence that supports it.","teaching":{"title":"A model answer shows the reasoning, not a single magic label","paragraphs":["The reference describes an earlier decline followed by more overlapping, less directional movement. It does not claim an exact candle marks the one true transition point.","Your turning points may differ slightly and still be defensible. Check whether your explanation identifies the earlier decline, notices the later overlap and acknowledges uncertainty about the transition."],"points":["Strong evidence: a sequence of generally lower turns earlier in the chart.","New evidence: more overlap and less directional progress later.","Good limitation: the precise transition point can be debated."],"takeaway":"Reward accurate observation and a defensible revision—not hindsight or pixel-perfect agreement."}}],alt:"Illustrative rising price sequence with no reference markings.",prompt:"What broad structure best describes the visible sequence?",instructions:"Point to the turns that support your label. Transition or unclear is acceptable when evidence is mixed.",cue:"Describe the larger swing sequence before bringing in zones or trade decisions.",quiz:{"q":"A rising sequence becomes more overlapping as new candles appear. What is the best response?","options":["Keep calling it rising because that was the first label.","Use the later evidence to consider a transition or possible range, while acknowledging uncertainty about the exact turning point.","Use the final chart to conclude the range should have been obvious from the first pause."],"correct":1,"feedback":"Structure is a description that can change with new evidence. Avoid hindsight: the later overlap may not have been clear in the earlier view."}},
    {id:3,module:2,title:"Identify meaningful swing points",duration:"15 min",summary:"A chart can contain many local peaks and troughs. Select the turns that carry useful structural information rather than treating every fluctuation as equally important.",outcome:"Choose a small, explainable set of swing points and say why minor turns were left out.",chart:"L03-A-01-clean.png",alt:"Illustrative over-marked teaching chart for selecting meaningful turns.",prompt:"Which turns deserve attention for the question you are asking?",instructions:"Name what makes a selected turn relevant to the broader structure. Do not justify a mark only because price later moved away from it.",cue:"A useful selection is selective and explainable; it is not a count of every visible wiggle.",quiz:{q:"What is the purpose of selecting meaningful swing points?",options:["To label every fluctuation.","To reduce noise by identifying turns relevant to the broader structure.","To know where price must reverse next."],correct:1,feedback:"The task is to separate meaningful structure from local noise—not to predict an exact reversal."}},
    {id:4,module:2,title:"Zones, not perfect lines",duration:"15 min",summary:"Related reactions may sit near one another without sharing an exact price. A zone makes room for that variation; its width should be defensible from the visible reactions.",outcome:"Explain why boundaries include some reactions and exclude others without claiming one exact answer always exists.",chart:"L04-A-01-clean.png",alt:"Illustrative lower reactions with wick and body variation, before boundaries are drawn.",prompt:"What evidence would help you defend the width of an area?",instructions:"Look across related reactions. Consider what a very narrow or very broad boundary would include or leave out.",cue:"Use a consistent convention and explain the trade-off. Precision is not the same as certainty.",quiz:{q:"Which statement best describes a zone boundary?",options:["There is one exact, universally correct price.","A defensible area accounts for relevant reactions and has an explainable width.","Always draw the same fixed number of ticks around a wick."],correct:1,feedback:"Boundary conventions can vary. What matters here is a consistent, evidence-based explanation."}},
    {id:5,module:2,title:"Choose the right areas and reduce clutter",duration:"18–22 min",summary:"Keep areas that help explain the chart and remove redundant or low-relevance marks. ChartLab 1, Clear W, practises that judgement on a controlled illustrative chart.",outcome:"Select a small number of relevant areas and explain what extra marks add—or fail to add.",chart:"CL01-01-clean.png",alt:"Clear W: illustrative W-like sequence with two related lower reactions and an upper reaction between them; no zones are drawn.",prompt:"Which areas would you keep to help explain the structure, and which would you leave unmarked?",instructions:"Make your first selection before comparing it with any reference. There is no need to mark every plausible area.",cue:"ChartLab reference overlays are not included in this preview. Explain what your selection clarifies and leaves out.",lab:"Clear W",labNo:1,quiz:{q:"When selecting areas for a readable chart, what is the best guide?",options:["Keep every plausible area so nothing is missed.","Keep a few areas relevant to the current question and explain the omissions.","Keep only the area closest to the latest candle."],correct:1,feedback:"Editing is part of analysis. Relevance to the current question matters more than filling the chart."}},
    {id:6,module:3,title:"Set defensible zone boundaries",duration:"16–19 min",summary:"Compare the reactions captured by a boundary with those it leaves outside. Use a convention you can explain.",outcome:"Set an area’s boundaries and give a concise rationale for its width and evidence.",chart:"L06-A-01-clean.png",alt:"Illustrative lower reactions for boundary practice, with zone edges hidden.",prompt:"Which parts of the visible reactions support your proposed top and bottom boundaries?",instructions:"Write what each edge includes and excludes. Alternative boundaries may be defensible if the reasoning is consistent.",cue:"Judge your explanation and consistency, not pixel-perfect overlap with a reference.",quiz:{q:"What should support a boundary choice?",options:["A clear explanation of the reactions included and excluded.","A promise that price will respect the exact edge.","A universal wick/body rule that fits every chart."],correct:0,feedback:"Boundaries should be explainable in context. They do not guarantee how price will behave next."}},
    {id:7,module:3,title:"Keep the chart readable",duration:"13–16 min",summary:"An area may be historically valid and still be unnecessary for the current question. Merge redundant marks and keep the chart useful rather than crowded.",outcome:"Edit a cluttered chart and explain why retained, merged or omitted marks help the current read.",chart:"L07-A-01-overmarked.png",alt:"Illustrative over-marked chart used to demonstrate editing and reducing clutter.",prompt:"Which marks add distinct information, and which ones repeat it?",instructions:"Think about the question you are trying to answer. An omitted area is not declared permanently irrelevant.",cue:"Keep a mark because it helps this analysis, not simply because it exists.",quiz:{q:"If two marked areas repeat the same information, what could you do?",options:["Keep both because more lines mean more certainty.","Consider merging or removing a redundant mark, with a reason.","Assume neither area will matter again."],correct:1,feedback:"The aim is a readable chart. Merging or omitting a mark for the current task does not make it permanently irrelevant."}},
    {id:8,module:3,title:"Evaluate a zone without inventing a magic score",duration:"18–22 min",summary:"Assess a zone in context: which reactions it captures, how consistent the evidence is, and what uncertainty remains. ChartLab 2 is Uneven Lows.",outcome:"Compare candidate areas qualitatively without turning touch count into a guarantee.",chart:"CL02-01-clean.png",alt:"Uneven Lows: illustrative sequence with two lower reactions at slightly different lows and a separate upper reaction area; no zones are drawn.",prompt:"How would you compare two lower reactions without demanding that their lows match exactly?",instructions:"Describe the evidence and uncertainty. Do not assign a numerical strength score or infer who placed orders.",cue:"Touch count by itself is not a probability. Compare what the zone captures and leaves out.",lab:"Uneven Lows",labNo:2,quiz:{q:"What does a larger number of touches establish by itself?",options:["A guaranteed stronger zone.","A universal numerical probability of holding.","Only that more visits are visible; significance still depends on context."],correct:2,feedback:"Touch count alone is not a universal score or outcome guarantee. Interpret the pattern in context."}},
    {id:9,module:4,title:"Read the approach to a zone",duration:"15–18 min",summary:"Notice the path towards an area: directional movement, overlapping candles, distance travelled and what remains uncertain. The authentic instructor micro-case remains pending.",outcome:"Describe the approach before interpreting how price behaves at an area.",chart:"L09-A-01-directional-approach.png",alt:"Illustrative directional approach; synthetic warm-up chart, not the authentic instructor case.",prompt:"What can you observe about the approach, and what remains unknown before the interaction?",instructions:"Separate visible movement from an explanation for why it is happening. The real instructor micro-case has not been supplied.",cue:"Approach context is evidence, not proof of intent or the outcome.",pending:{title:"Authentic instructor micro-case pending",copy:"This synthetic chart is a preparation example only. The instructor’s actual pre-interaction chart and original rationale have not been supplied; they will not be invented."},quiz:{q:"What is a sound first step when reading an approach?",options:["Assume the approaching move must continue.","Describe the visible path and keep the reason for it provisional.","Infer institutional intent from the chart alone."],correct:1,feedback:"Describe what can be seen. A chart alone does not establish intent or guarantee the next path."}},
    {id:10,module:4,title:"Rejection versus acceptance",duration:"17–19 min",summary:"A wick near an area is not enough to settle rejection or acceptance. Look at closes, follow-through and the sequence that develops.",outcome:"Describe the interaction and state what additional evidence would strengthen or weaken your read.",chart:"L10-A-01-first-interaction.png",alt:"Illustrative first interaction with an area; later evidence is hidden.",prompt:"What do you observe at the first interaction, and what evidence would you wait for next?",instructions:"Describe the visible candle behaviour first. Keep more than one interpretation possible.",cue:"A single wick does not settle the interpretation. Let the sequence refine the view.",quiz:{q:"What helps distinguish rejection from acceptance?",options:["The first wick by itself.","The sequence of closes and follow-through around the area.","A belief about who is trading."],correct:1,feedback:"Use the sequence and later evidence. One wick alone does not prove acceptance or rejection."}},
    {id:11,module:4,title:"How a zone’s significance changes",duration:"17–19 min",summary:"Later visits may change the context of a zone. Preserve the original read and log what new evidence changes your interpretation.",outcome:"Track what changed and explain how that evidence affects—but does not automatically settle—the interpretation.",chart:"L11-01-first-reaction.png",alt:"Illustrative timeline stage showing the initial reaction; later states are not shown here.",prompt:"What new evidence would make you keep, weaken or reconsider your original read?",instructions:"Keep the first observation visible. Separate what changed on the chart from how you interpret that change.",cue:"Update honestly rather than claiming hindsight made the right answer obvious.",quiz:{q:"When later evidence changes your view, what is useful to preserve?",options:["Only the final explanation.","The initial observation and the evidence that caused you to revise it.","A claim that the new view was certain from the start."],correct:1,feedback:"Preserving the initial read makes the reasoning process visible and helps reduce hindsight bias."}},
    {id:12,module:5,title:"Breakout or temporary penetration?",duration:"17–19 min",summary:"Price can cross an area and return, or it can continue beyond it. Distinguish the crossing you observe from the thesis you form.",outcome:"Describe the crossing, set out plausible alternatives and avoid treating one candle as conclusive.",chart:"L12-A-01-first-crossing.png",alt:"Illustrative initial crossing of a prior range boundary; return candles are hidden.",prompt:"What can you say about the crossing now, and what remains unresolved?",instructions:"Describe the observable event first. Name evidence that would support either continuation or a return.",cue:"The first cross is a data point in a sequence, not proof of what follows.",quiz:{q:"What does the first move beyond a zone establish?",options:["That continuation is guaranteed.","That price crossed the area; follow-through and alternatives remain to be assessed.","That the old zone must reverse roles."],correct:1,feedback:"Describe the crossing without assuming the outcome. Follow-through, return and mixed evidence remain possible."}},
    {id:13,module:5,title:"Retests and role reversal",duration:"15–18 min",summary:"A return to a broken area may occur, and a former resistance area may later behave as support (or the reverse). Neither a retest nor a role change is compulsory.",outcome:"Describe both a possible hold and a failure when price revisits an area.",chart:"L13-A-01-break-beyond.png",alt:"Illustrative price sequence beyond a former resistance area; later return is hidden.",prompt:"If price returns to the prior area, what are two plausible ways the sequence could develop?",instructions:"State what you would watch for in each case. Do not make a retest mandatory in your reasoning.",cue:"Role reversal is a possible interpretation to test—not a rule every chart must follow.",quiz:{q:"Which statement about a retest is most accurate?",options:["Every valid breakout must retest its zone.","A retest may occur; the old role can change or the attempt can fail.","Once crossed, a zone can never matter again."],correct:1,feedback:"A retest is possible, not required. Role reversal is conditional and can fail."}},
    {id:14,module:5,title:"Failed breakouts and alternate outcomes",duration:"18–22 min",summary:"A move beyond a zone may fail to sustain itself. Revise a provisional breakout interpretation when later evidence challenges it. ChartLab 3, Wider Neckline, is the final ChartLab.",outcome:"Identify what challenges a breakout thesis, preserve a plausible alternative and explain a defensible zone without hindsight.",chart:"CL03-01-clean.png",alt:"Wider Neckline: illustrative W-like structure with a broader upper reaction area; no zones are drawn.",prompt:"What would challenge the first breakout interpretation, and how would you revise your read?",instructions:"Try the clean chart first. A different but evidence-based zone can be defensible; do not infer that failure was obvious beforehand.",cue:"This is the third and final ChartLab. The reference overlay is intentionally absent from this preview.",lab:"Wider Neckline",labNo:3,quiz:{q:"If later price action returns through the area after a breakout attempt, what should you do?",options:["Keep the breakout thesis unchanged no matter what.","Reassess the thesis in light of the new sequence and consider alternatives.","Claim the failure was obvious from the first candle."],correct:1,feedback:"A disciplined read is revisable. Describe the evidence that challenged the original interpretation without hindsight."}},
    {id:15,module:6,title:"From zones to conditional scenarios",duration:"18–22 min",summary:"Use zones as context for conditional reasoning, not as standalone buy/sell instructions. Consider alternatives, invalidation, space to the next area and whether waiting is more defensible.",outcome:"Write an if/then scenario, state what would make you reconsider, and include an alternative or a justified decision to wait.",chart:"L15-A-01-clean.png",alt:"Illustrative context between two candidate areas with answers hidden.",prompt:"With price between two areas, write two conditional paths—or one path and a reasoned decision to wait.",instructions:"For each path, say what evidence would make it more plausible and what would make you reconsider.",cue:"A scenario describes conditions and alternatives. It is not an order or a promise of outcome.",quiz:{q:"What turns a zone observation into a more complete conditional analysis?",options:["A fixed buy/sell instruction at the boundary.","An if/then scenario, an alternative and evidence that would invalidate or weaken the idea.","Assuming the next opposing zone is a guaranteed target."],correct:1,feedback:"Conditional scenarios include alternatives and reconsideration. A zone is not a complete trade plan or guaranteed target."}},
    {id:16,module:6,title:"Case study: a trade based on a reaction",duration:"20–25 min",summary:"This lesson should follow one real instructor trade from pre-entry information through execution, management, exit and review. It demonstrates process and uncertainty—not a signal to copy.",outcome:"When authentic records are supplied, evaluate reasoning at each decision point separately from the final outcome.",prompt:"Before reviewing a real trade, what contemporaneous evidence would you need to judge the decision fairly?",instructions:"Preparation prompt only. The substantive case and its decision checkpoints remain pending until authentic records are available.",cue:"No fake case or outcome is used to fill this space.",pending:{title:"Authentic instructor trade record pending",copy:"The real chart, entry, risk, management and exit evidence has not been supplied. No trade, price, result or instructor rationale is invented."}},
    {id:17,module:6,title:"Case study: when the thesis fails, or you stay out",duration:"18–24 min",summary:"This lesson will examine an authentic failed thesis, losing trade or stand-aside decision. It will distinguish thesis failure from process failure.",outcome:"When authentic evidence is added, explain what changed and how process quality differs from outcome.",prompt:"What is the difference between a thesis failing and the decision process being poor?",instructions:"This is a preparation reflection, not a substitute for the authentic case. The evidence and review sequence remain pending.",cue:"The real example must be supplied before this can be reviewed as substantive course content.",pending:{title:"Authentic failed-thesis or no-trade example pending",copy:"A genuine instructor example and candid review have not been supplied. The prototype will not fabricate a loss, missed trade, stand-aside decision or hindsight explanation."}},
    {id:18,module:6,title:"Final chart review and knowledge check",duration:"30–35 min",summary:"Bring the method together on an unfamiliar chart: describe structure, select and defend zones, interpret current behaviour, build conditional scenarios and state what would change your view.",outcome:"Present a coherent chart-reading rationale, allow uncertainty, and separate reasoning quality from eventual price outcome.",prompt:"On an unfamiliar chart, what structure do you see, which areas can you defend, and what would make you change your view?",instructions:"The full unseen-chart assessment, score policy, retry and gated reference reveal are not implemented in this preview.",cue:"This lesson is an assessment shell only. No answer key or final reference is shown here.",assessment:true}
  ];
  const emptyState = () => ({active:1,statuses:{},responses:{},attempts:{},notes:{},quizChoices:{},quizSubmitted:{},chartStages:{}});
  let saved = loadState();
  let activeId = Number(saved.active) || 1;
  let activeTab = "lesson";
  function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return emptyState();return {...emptyState(),...JSON.parse(raw)}}catch(_){return emptyState()}}
  function saveState(){
    saved.active=activeId;
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(saved));setSaveMessage("sr-response-save-state","Saved in this browser only");setSaveMessage("sr-notes-save-state","Saved in this browser only");renderProgress()}
    catch(_){setSaveMessage("sr-response-save-state","Could not save in this browser");setSaveMessage("sr-notes-save-state","Could not save in this browser")}
  }
  function setSaveMessage(id,message){const el=$(id);if(el)el.textContent=message}
  function moduleFor(id){return modules.find(m=>m.id===id)}
  function lessonFor(id){return lessons.find(l=>l.id===id)||lessons[0]}
  function statusOf(id){return saved.statuses[id]||"not-started"}
  function markInProgress(id){if(statusOf(id)==="not-started")saved.statuses[id]="in-progress"}
  function completionCount(){return lessons.filter(l=>statusOf(l.id)==="complete").length}
  function renderProgress(){
    const count=completionCount(),percent=Math.round(count/lessons.length*100);
    $("sr-course-progress-bar").style.width=percent+"%";
    $("sr-course-progress-label").textContent=count+" of "+lessons.length+" lessons complete";
    $("sr-course-progress-percent").textContent=percent+"%";
    $("sr-resume-copy").textContent="Lesson "+activeId+" · "+lessonFor(activeId).title;
  }
  function renderModuleCards(){
    $("sr-module-cards").innerHTML=modules.map(m=>{
      const rows=lessons.filter(l=>l.module===m.id),done=rows.filter(l=>statusOf(l.id)==="complete").length;
      return '<button type="button" class="sr-room-module-card'+(rows.some(l=>l.id===activeId)?" is-current":"")+'" data-module-card="'+m.id+'"><span class="index">0'+m.id+'</span><strong>'+m.name+'</strong><small>'+m.range+" · "+done+"/"+rows.length+' complete</small><small>'+m.outcome+'</small></button>';
    }).join("");
    $("sr-module-cards").querySelectorAll("[data-module-card]").forEach(btn=>btn.addEventListener("click",()=>{const first=lessons.find(l=>l.module===Number(btn.dataset.moduleCard));if(first)selectLesson(first.id,true);$("sr-lesson-workspace").scrollIntoView({behavior:"smooth",block:"start"})}));
  }
  function renderOutline(){
    const query=$("sr-lesson-search").value.trim().toLowerCase(),modFilter=$("sr-module-filter").value,statusFilter=$("sr-status-filter").value;
    let visible=0,markup="";
    modules.forEach(m=>{
      if(modFilter!=="all"&&Number(modFilter)!==m.id)return;
      const rows=lessons.filter(l=>l.module===m.id&&(l.title+" "+l.summary+" "+(l.prompt||"")).toLowerCase().includes(query)&&(statusFilter==="all"||statusOf(l.id)===statusFilter));
      if(!rows.length)return;visible+=rows.length;
      markup+='<section class="sr-room-module-group"><div class="sr-room-module-group-head"><strong>'+m.name+'</strong><small>'+m.range+'</small></div>';
      markup+=rows.map(l=>'<button type="button" class="sr-room-lesson-link'+(l.id===activeId?" is-active":"")+'" data-lesson-id="'+l.id+'" data-state="'+statusOf(l.id)+'"><span class="lesson-n">'+String(l.id).padStart(2,"0")+'</span><span class="lesson-title">'+l.title+'</span><span class="lesson-state" aria-hidden="true"></span></button>').join("");
      markup+="</section>";
    });
    $("sr-lesson-list").innerHTML=markup||'<p class="sr-room-outline-foot">No lessons match these filters.</p>';
    $("sr-outline-count").textContent=visible;
    $("sr-lesson-list").querySelectorAll("[data-lesson-id]").forEach(btn=>btn.addEventListener("click",()=>selectLesson(Number(btn.dataset.lessonId),true)));
    renderModuleCards();
  }
  function setTab(tab){
    activeTab=tab;
    ["lesson","notes","check"].forEach(name=>{
      const button=$("sr-tab-button-"+name),panel=$("sr-tab-"+name),active=name===tab;
      button.classList.toggle("is-active",active);button.setAttribute("aria-selected",String(active));button.tabIndex=active?0:-1;panel.hidden=!active;
    });
  }
  function renderQuiz(l){
    const root=$("sr-quiz-content");root.innerHTML="";
    if(!l.quiz){
      const info=document.createElement("div");info.className="sr-room-feedback";
      info.textContent=l.assessment?"The unseen assessment is not active in this preview. Submission, rubric scoring, retry and gated reference delivery need a tested implementation.":"A knowledge check will be added when authentic lesson material is available. No answer key is fabricated for this lesson.";
      root.append(info);return;
    }
    $("sr-check-title").textContent=l.quiz.q;$("sr-check-intro").textContent="Choose a response and submit it to view this preview’s explanation.";
    const options=document.createElement("div");options.className="sr-room-quiz-options";options.setAttribute("role","group");options.setAttribute("aria-label","Answer options");
    l.quiz.options.forEach((opt,index)=>{
      const b=document.createElement("button");b.type="button";b.className="sr-room-quiz-option";b.setAttribute("aria-pressed",String(saved.quizChoices[l.id]===index));
      b.innerHTML='<span class="sr-room-quiz-letter">'+String.fromCharCode(65+index)+'</span><span></span>';b.lastElementChild.textContent=opt;
      b.addEventListener("click",()=>{saved.quizChoices[l.id]=index;delete saved.quizSubmitted[l.id];options.querySelectorAll("button").forEach((other,i)=>other.setAttribute("aria-pressed",String(i===index)));const old=$("sr-quiz-feedback");if(old)old.remove();saveState()});
      options.append(b);
    });
    root.append(options);
    const submit=document.createElement("button");submit.type="button";submit.className="button sr-room-primary";submit.textContent="Submit answer";
    submit.addEventListener("click",()=>{
      if(!Number.isInteger(saved.quizChoices[l.id])){let message=$("sr-quiz-feedback");if(!message){message=document.createElement("div");message.id="sr-quiz-feedback";message.className="sr-room-feedback";root.append(message)}message.textContent="Choose a response before submitting.";return}
      saved.quizSubmitted[l.id]=saved.quizChoices[l.id];saveState();renderQuiz(l);
    });
    root.append(submit);
    if(saved.quizSubmitted[l.id]!==undefined){
      const correct=saved.quizSubmitted[l.id]===l.quiz.correct,feedback=document.createElement("div");
      feedback.id="sr-quiz-feedback";feedback.className="sr-room-feedback";feedback.setAttribute("role","status");
      feedback.textContent=(correct?"That fits the lesson. ":"Review the distinction. ")+l.quiz.feedback;root.append(feedback);
    }
  }
  function chartStageIndex(l){
    const stages=l.chartStages;
    if(!Array.isArray(stages)||!stages.length)return 0;
    const value=Number((saved.chartStages||{})[l.id]);
    return Number.isFinite(value)?Math.max(0,Math.min(stages.length-1,value)):0;
  }
  function updateChartStageControls(l){
    const controls=$("sr-chart-controls"),stages=l.chartStages;
    if(!controls)return;
    if(!Array.isArray(stages)||stages.length<2){controls.hidden=true;return}
    controls.hidden=false;
    const index=chartStageIndex(l),attempted=!!saved.attempts[l.id]||!!((saved.responses[l.id]||"").trim());
    const previous=$("sr-chart-prev"),next=$("sr-chart-next");
    previous.disabled=index===0;
    next.disabled=index===stages.length-1||(index===0&&!attempted);
    next.textContent=index===stages.length-1?"End of sequence":"Reveal next view →";
    $("sr-chart-stage-count").textContent="View "+(index+1)+" of "+stages.length;
    $("sr-chart-stage-status").textContent=stages[index].label;
    $("sr-chart-reveal-guidance").textContent=index===0&&!attempted
      ?"Write your first read below or tick “I have made an attempt” before revealing the next view."
      :index===stages.length-1
        ?"You have reached the end of this sequence. You can revisit earlier views to compare what changed."
        :"Compare the visible evidence with your first read before moving on.";
  }
  function renderTeaching(l,stage){
    const panel=$("sr-teaching-content");
    if(!panel)return;
    const teaching=stage&&stage.teaching;
    if(!teaching){panel.hidden=true;return}
    panel.hidden=false;
    $("sr-teaching-kicker").textContent=stage.label.startsWith("Your turn")?"YOUR PRACTICE":stage.label.startsWith("Worked answer")?"WORKED REASONING":"WHAT TO NOTICE";
    $("sr-teaching-title").textContent=teaching.title||"What the chart supports";
    const body=$("sr-teaching-body");body.replaceChildren();
    (teaching.paragraphs||[]).forEach(copy=>{const p=document.createElement("p");p.textContent=copy;body.append(p)});
    if((teaching.points||[]).length){
      const ul=document.createElement("ul");
      teaching.points.forEach(copy=>{const li=document.createElement("li");li.textContent=copy;ul.append(li)});
      body.append(ul);
    }
    $("sr-teaching-takeaway").textContent=teaching.takeaway||"Describe the evidence and keep uncertainty visible.";
  }
  function renderChart(l){
    const figure=$("sr-chart-figure"),img=$("sr-chart-image"),fallback=$("sr-chart-fallback"),controls=$("sr-chart-controls");
    const stages=l.chartStages,stage=Array.isArray(stages)&&stages.length?stages[chartStageIndex(l)]:null;
    if(!l.chart){figure.hidden=true;img.removeAttribute("src");controls.hidden=true;renderTeaching(l,null);return}
    figure.hidden=false;img.hidden=false;fallback.hidden=true;
    img.alt=stage?stage.alt:l.alt;
    img.onerror=()=>{img.hidden=true;fallback.hidden=false};
    img.onload=()=>{img.hidden=false;fallback.hidden=true};
    img.src=chartRoot+(stage?stage.file:l.chart);
    $("sr-chart-label").textContent=stage?stage.label:(l.lab?"ChartLab "+l.labNo+" · "+l.lab:"Illustrative chart");
    $("sr-chart-caption").textContent="Illustrative chart — not historical market data. "+(stage?stage.caption:"Use the visible chart as evidence for the prompt; avoid treating it as a prediction.");
    $("sr-practice-prompt").textContent=(stage&&stage.question)||l.prompt;
    $("sr-practice-instructions").textContent=(stage&&stage.instructions)||l.instructions;
    $("sr-practice-cue").textContent=(stage&&stage.cue)||l.cue;
    renderTeaching(l,stage);
    updateChartStageControls(l);
  }
  function moveChartStage(direction){
    const l=lessonFor(activeId),stages=l.chartStages;
    if(!Array.isArray(stages)||!stages.length)return;
    const index=chartStageIndex(l),attempted=!!saved.attempts[l.id]||!!((saved.responses[l.id]||"").trim());
    if(direction>0&&index===0&&!attempted)return;
    saved.chartStages=saved.chartStages||{};
    saved.chartStages[l.id]=Math.max(0,Math.min(stages.length-1,index+direction));
    saveState();renderChart(l);
  }

  function renderLesson(){
    const l=lessonFor(activeId),m=moduleFor(l.module),state=statusOf(l.id);
    $("sr-lesson-number").textContent="LESSON "+String(l.id).padStart(2,"0")+" / 18";$("sr-lesson-module").textContent=m.name.toUpperCase();
    $("sr-lesson-title").textContent=l.title;$("sr-lesson-summary").textContent=l.summary;$("sr-lesson-outcome").textContent=l.outcome;
    $("sr-lesson-state").textContent=state.replace("-"," ").toUpperCase();$("sr-lesson-state").dataset.state=state;
    const tags=[l.duration+" · estimated"];if(l.lab)tags.push("ChartLab "+l.labNo+" · "+l.lab);if(l.pending)tags.push("Authentic material pending");if(l.assessment)tags.push("Assessment shell only");
    $("sr-lesson-tags").innerHTML=tags.map(t=>'<span class="sr-room-tag'+(t.startsWith("ChartLab")?" is-lab":"")+'">'+t+'</span>').join("");
    const pending=$("sr-pending-material");pending.hidden=!l.pending;if(l.pending){$("sr-pending-title").textContent=l.pending.title;$("sr-pending-copy").textContent=l.pending.copy}
    $("sr-practice-prompt").textContent=l.prompt;$("sr-practice-instructions").textContent=l.instructions;$("sr-practice-cue").textContent=l.cue;
    renderChart(l);
    $("sr-practice-response").value=saved.responses[l.id]||"";$("sr-attempt-made").checked=!!saved.attempts[l.id];$("sr-response-save-state").textContent="Saved in this browser only";
    $("sr-lesson-notes").value=saved.notes[l.id]||"";$("sr-notes-save-state").textContent="Saved in this browser only";
    $("sr-complete-button").textContent=state==="complete"?"Completed ✓ · undo":"Mark complete ✓";$("sr-complete-button").classList.toggle("is-complete",state==="complete");
    $("sr-previous-button").disabled=l.id===1;$("sr-next-button").textContent=l.id===18?"Back to course outline ↗":"Next lesson →";
    $("sr-navigation-status").textContent="Lesson "+l.id+" of "+lessons.length;$("sr-bottom-help").textContent=l.pending?"This lesson stays visibly pending until authentic instructor material is supplied.":l.assessment?"Assessment submission, retry and reference gates are not simulated as production-ready.":"Take your time. The point is a reasoned read, not a prediction.";
    $("sr-resume-button").textContent="Open lesson "+String(l.id).padStart(2,"0")+" ↗";
    renderQuiz(l);renderOutline();renderProgress();setTab(activeTab);
  }
  function selectLesson(id,mark=true){if(!lessons.some(l=>l.id===id))return;activeId=id;if(mark)markInProgress(id);saved.active=id;saveState();renderLesson()}
  $("sr-resume-button").addEventListener("click",()=>$("sr-lesson-workspace").scrollIntoView({behavior:"smooth",block:"start"}));
  $("sr-previous-button").addEventListener("click",()=>{if(activeId>1)selectLesson(activeId-1,true)});
  $("sr-next-button").addEventListener("click",()=>{if(activeId<18)selectLesson(activeId+1,true);else $("sr-room-top").scrollIntoView({behavior:"smooth",block:"start"})});
  $("sr-complete-button").addEventListener("click",()=>{saved.statuses[activeId]=statusOf(activeId)==="complete"?"in-progress":"complete";saveState();renderLesson()});
  $("sr-chart-prev").addEventListener("click",()=>moveChartStage(-1));
  $("sr-chart-next").addEventListener("click",()=>moveChartStage(1));
  document.querySelectorAll("[data-sr-tab]").forEach(btn=>btn.addEventListener("click",()=>setTab(btn.dataset.srTab)));
  $("sr-lesson-search").addEventListener("input",renderOutline);$("sr-module-filter").addEventListener("change",renderOutline);$("sr-status-filter").addEventListener("change",renderOutline);
  $("sr-practice-response").addEventListener("input",()=>{saved.responses[activeId]=$("sr-practice-response").value;saveState();updateChartStageControls(lessonFor(activeId))});
  $("sr-attempt-made").addEventListener("change",()=>{saved.attempts[activeId]=$("sr-attempt-made").checked;saveState();updateChartStageControls(lessonFor(activeId))});
  $("sr-lesson-notes").addEventListener("input",()=>{saved.notes[activeId]=$("sr-lesson-notes").value;saveState()});
  $("sr-clear-notes").addEventListener("click",()=>{if(!confirm("Clear notes for this lesson from this browser?"))return;delete saved.notes[activeId];saveState();$("sr-lesson-notes").value="";$("sr-notes-save-state").textContent="Notes cleared in this browser."});
  $("sr-module-filter").insertAdjacentHTML("beforeend",modules.map(m=>'<option value="'+m.id+'">'+m.id+". "+m.name+'</option>').join(""));
  renderLesson();
})();